export const CHAPEL_OBJECTIVES={chapter_complete:'Поговорите с Джоном о затопленной часовне',chapel_travel:'Пройдите к часовне за южным краем кладбища',chapel_echoes:'Найдите три отголоска прошлого в затопленной часовне',chapel_choice:'Коснитесь колокола и решите судьбу печати',chapel_return:'Вернитесь к Джону',chapel_done:'Колокол умолк · исследуйте Темнолесье, пока не открылся новый путь'};
export const chapelUnlocked=p=>p.stage.startsWith('chapel_')||p.rewards.includes('chapel-quest');
const ECHO_TEXTS=[
 'Вода отражает чужое утро. Ты видишь себя у колокола. Рядом женщина с медальона. «Лиора, если я забуду — не зови меня по имени». Она обещает, но её руки дрожат.',
 'На затопленной дороге лежат пустые гробы. Люди отдавали Личу воспоминания, чтобы мёртвые не узнавали их. Ты предложил больше: собственное имя, способное запереть проход под часовней.',
 'Ты видишь Джона гораздо моложе. Он спрашивает: «А если вернёшься?» Ты отвечаешь: «Сначала испытай меня. Если тень окажется сильнее, не открывай могилу». Лиора остаётся по другую сторону печати.'];
export function chapelQuest({p,world,show,close,sync,sound,reward}){
 function tick(){if(world?.inside&&p.stage==='chapel_travel'){p.stage='chapel_echoes';sync()}if(p.stage==='chapel_echoes'&&world?.found.every(Boolean)){p.stage='chapel_choice';sync()}}
 function talk(){if(p.stage==='chapter_complete'){show('Джон','Путь к часовне освободился после гибели Хранителя. За твоей могилой, в южном конце кладбища, стоит старая арка. Пройди через неё.\nКолокол звонит без языка: это не звук, а память. Собери три отголоска у руин, дороги и алтаря. Затем реши, что ты готов вернуть.',[['Я отправлюсь к часовне',()=>{p.stage='chapel_travel';sound();sync();close()}],['Мне нужно подготовиться',close]]);return true}if(p.stage==='chapel_return'){reward(p,'chapel-quest','quest',120);p.stage='chapel_done';sound();sync();show('Джон',world?.choice==='memory'?'Значит, её звали Лиора. Ты вернул имя и услышал голос. Теперь печать слабеет, а те, кто ждёт за ней, знают, что ты жив. Я не осуждаю тебя. Но искать её придётся с открытыми глазами.\nКолокол без звонаря умолк. Дальше нам предстоит найти сердце печати.':'Ты оставил её за печатью, чтобы деревня могла жить. Забыть было легче, чем снова принять это решение. Теперь ты знаешь цену своей прошлой жертвы — и всё ещё остаёшься собой.\nКолокол умолк, вода стала спокойнее. Мы найдём другой путь к сердцу печати.');return true}if(p.stage.startsWith('chapel_')){show('Джон',p.stage==='chapel_done'?'Сердце печати скрыто глубже, чем владения Лича. Пока исследуй оставшиеся руины и приготовься к следующему пути.':'Южная арка за твоей могилой ведёт к часовне. Три отголоска помогут понять, что случилось; только после этого касайся колокола.');return true}return false}
 function decide(value){if(p.stage!=='chapel_choice'||!world.setChoice(value))return;p.stage='chapel_return';sync();sound();show(value==='memory'?'Вернуть память':'Укрепить печать',value==='memory'?'Имя Лиоры перестаёт быть чужим. На мгновение ты слышишь её голос. Вода вспыхивает фиолетовым светом: печать удержалась, но стала тоньше. Джон должен узнать о твоём выборе.':'Ты вплетаешь отголоски обратно в печать. Колокол умолкает, зелёный свет смягчается. Лиора остаётся за чертой, но теперь ты помнишь, почему сделал этот выбор. Расскажи Джону.')}
 function interact(){if(!world)return;if(!world.inside){if(!chapelUnlocked(p))return show('Дорога к часовне','За аркой клубится плотный туман. Сначала поговори с Джоном о медальоне и пустой могиле.');world.enter();tick();sync();return}const action=world.action();if(!action)return;if(action.type==='exit'){world.leave();sync();return}if(action.type==='echo'){if(!['chapel_echoes','chapel_choice'].includes(p.stage))return show('Отголосок','Эта память пока не отвечает.');if(world.collect(action.index)){tick();sync();sound();show('Отголосок '+(action.index+1),ECHO_TEXTS[action.index]+'\n\nНайдено: '+world.found.filter(Boolean).length+' / 3.')}return}if(action.type==='bell'){if(p.stage==='chapel_choice')show('Колокол без звонаря','Теперь ты помнишь: твой добровольный обет запер путь, на другой стороне которого осталась Лиора. Колокол предлагает вернуть часть памяти — или укрепить печать. Выбор сохранится.',[['Вернуть память о Лиоре',()=>decide('memory')],['Укрепить печать ради деревни',()=>decide('seal')],['Я ещё не готов',close]]);else show('Колокол без звонаря',world.choice?'Колокол умолк. Твой выбор уже сделан.':'На языке колокола нет металла — только пустота. Сначала найди три отголоска своей памяти.')}}
 return {tick,talk,interact};
}
